/// <summary>
/// The METTransferOrderLoadPlanningAidController class is the helper class for the associated SRS Report.
/// </summary>
class METTransferOrderLoadPlanningAidController extends SrsReportRunController
{
}

Method.Source:
public static METTransferOrderLoadPlanningAidController construct()
{
    return new METTransferOrderLoadPlanningAidController();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    METTransferOrderLoadPlanningAidController controller = METTransferOrderLoadPlanningAidController::construct();

    controller.parmReportName(ssrsReportStr(METTransferOrderLoadPlanningAidReport, Report));
    controller.parmArgs(_args);
    controller.parmShowDialog(false);
    METTransferOrderLoadPlanningAidContract transferOrderLoadPlanningAidContract = controller.parmReportContract().parmRdpContract() as METTransferOrderLoadPlanningAidContract;
    MetTransferOrderExtractScreenParameters metTransferOrderExtractScreenParameters = _args.parmObject();

    if (metTransferOrderExtractScreenParameters && transferOrderLoadPlanningAidContract)
    {
        str selectedExtratedOrders = _args.parm();
        if (strLen(selectedExtratedOrders) > 0)
        {
            transferOrderLoadPlanningAidContract.parmSelectedRecords(selectedExtratedOrders);
        }

        transferOrderLoadPlanningAidContract.parmConfirmedShipDateFrom(metTransferOrderExtractScreenParameters.parmShippingDateConfirmFrom());
        transferOrderLoadPlanningAidContract.parmConfirmedShipDateTo(metTransferOrderExtractScreenParameters.parmShippingDateConfirmTo());
        transferOrderLoadPlanningAidContract.parmInventLocationFrom(metTransferOrderExtractScreenParameters.parmFromWarehouse());
        transferOrderLoadPlanningAidContract.parmInventLocationTo(metTransferOrderExtractScreenParameters.parmToWarehouse());
        transferOrderLoadPlanningAidContract.parmRouteID(metTransferOrderExtractScreenParameters.parmRoute());
    }

    controller.startOperation();
}
